import{_ as l,a0 as o,w as d,s as c,ao as p,I as n,x as a,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"一些被忽略的 Git 知識 | LCTT x X-CMD","titleTemplate":false,"description":"一些被忽略的 Git 知識 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一些被忽略的 Git 知識 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一些被忽略的 Git 知識 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20231020 Some miscellaneous git facts","title":"一些被忽略的 Git 知識","tag":"202310","desc":""},"relativePath":"202310/20231020 Some miscellaneous git facts.md","filePath":"[post].md"}'),g={name:"202310/20231020 Some miscellaneous git facts.md"};function r(h,s,f,u,b,k){const e=o("Link");return d(),c("div",null,[s[20]||(s[20]=p(`<h1 id="一些被忽略的-git-知識" tabindex="-1">一些被忽略的 Git 知識 <a class="header-anchor" href="#一些被忽略的-git-知識" aria-label="Permalink to “一些被忽略的 Git 知識”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/25/122259mfu0uowyppuyfdyo.jpg" alt=""></p><p>我一直在慢慢地撰寫關於 Git 工作原理的文章。儘管我曾認為自己對 Git 非常瞭解，但像往常一樣，當我嘗試解釋某事的時候，我又學到一些新東西。</p><p>現在回想起來，這些事情都不算太令人吃驚，但我以前並沒有清楚地思考過它們。</p><p>事實是:</p><ul><li>“索引”、“暫存區” 和 <code>-cached</code> 是一回事</li><li>隱匿文件就是一堆提交</li><li>並非所有引用都是分支或標籤</li><li>合併提交不是空的</li></ul><p>下面我們來詳細瞭解這些內容。</p><h3 id="索引-、-暫存區-和-cached-是一回事" tabindex="-1">“索引”、“暫存區” 和 <code>-cached</code> 是一回事 <a class="header-anchor" href="#索引-、-暫存區-和-cached-是一回事" aria-label="Permalink to ““索引”、“暫存區” 和 -cached 是一回事”">​</a></h3><p>當你運行 <code>git add file.txt</code>，然後運行 <code>git status</code>，你會看到類似以下的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git add content/post/2023-10-20-some-miscellaneous-git-facts.markdown</span></span>
<span class="line"><span>$ git status</span></span>
<span class="line"><span>Changes to be committed:</span></span>
<span class="line"><span>    (use &quot;git restore --staged &lt;file&gt;...&quot; to unstage)</span></span>
<span class="line"><span>    new file:   content/post/2023-10-20-some-miscellaneous-git-facts.markdown</span></span></code></pre></div><p>人們通常稱這個過程為“暫存文件”或“將文件添加到暫存區”。</p><p>當你使用 <code>git add</code> 命令來暫存文件時，Git 在後台將文件添加到其對象資料庫（在 <code>.git/objects</code> 目錄下），並更新一個名為 <code>.git/index</code> 的文件以引用新添加的文件。</p><p>Git 中的這個“暫存區”事實上有 3 種不同的名稱，但它們都指的是同一個東西（即 <code>.git/index</code> 文件）：</p><ul><li><code>git diff --cached</code></li><li><code>git diff --staged</code></li><li><code>.git/index</code> 文件</li></ul><p>我覺得我早該早點認識到這一點，但我之前並沒有，所以在這裏提醒一下。</p><h3 id="隱匿文件就是一堆提交" tabindex="-1">隱匿文件就是一堆提交 <a class="header-anchor" href="#隱匿文件就是一堆提交" aria-label="Permalink to “隱匿文件就是一堆提交”">​</a></h3><p>當我運行 <code>git stash</code> 命令來保存更改時，我一直對這些更改究竟去了哪裏感到有些困惑。事實上，當你運行 <code>git stash</code> 命令時，Git 會根據你的更改創建一些提交，並用一個名為 <code>stash</code> 的引用來標記它們（在 <code>.git/refs/stash</code> 目錄下）。</p><p>讓我們將此Blog文章隱匿起來，然後查看 <code>stash</code> 引用的日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log stash --oneline</span></span>
<span class="line"><span>6cb983fe (refs/stash) WIP on main: c6ee55ed wip</span></span>
<span class="line"><span>2ff2c273 index on main: c6ee55ed wip</span></span>
<span class="line"><span>... some more stuff</span></span></code></pre></div><p>現在我們可以查看提交 <code>2ff2c273</code> 以查看其包含的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git show 2ff2c273  --stat</span></span>
<span class="line"><span>commit 2ff2c273357c94a0087104f776a8dd28ee467769</span></span>
<span class="line"><span>Author: Julia Evans &lt;julia@jvns.ca&gt;</span></span>
<span class="line"><span>Date:   Fri Oct 20 14:49:20 2023 -0400</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    index on main: c6ee55ed wip</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    content/post/2023-10-20-some-miscellaneous-git-facts.markdown | 40 ++++++++++++++++++++++++++++++++++++++++</span></span></code></pre></div><p>毫不意外，它包含了這篇Blog文章。這很合理！</p><p>實際上，<code>git stash</code> 會創建兩個獨立的提交：一個是索引提交，另一個是你尚未暫存的改動提交。這讓我感到很振奮，因為我一直在開發一款工具，用於快照和恢復 Git 倉庫的狀態（也許永遠不會發布），而我提出的設計與 Git 的隱匿實現非常相似，所以我對自己的選擇感到滿意。</p><p>顯然 <code>stash</code> 中的舊提交存儲在 reflog 中。</p><h3 id="並非所有引用都是分支或標籤" tabindex="-1">並非所有引用都是分支或標籤 <a class="header-anchor" href="#並非所有引用都是分支或標籤" aria-label="Permalink to “並非所有引用都是分支或標籤”">​</a></h3><p>Git 文檔中經常泛泛地提到 “引用”，這使得我有時覺得很困惑。就個人而言，我在 Git 中處理 “引用” 的 99% 時間是指分支或 HEAD，而剩下的 1% 時間是指標籤。事實上，我以前完全不知道任何不是分支、標籤或 <code>HEAD</code> 的引用示例。</p><p>但現在我知道了一個例子—— <code>stash</code> 是一種引用，而它既不是分支也不是標籤！所以這太酷啦！</p><p>以下是我Blog的 Git 倉庫中的所有引用（除了 <code>HEAD</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find .git/refs -type f</span></span>
<span class="line"><span>.git/refs/heads/main</span></span>
<span class="line"><span>.git/refs/remotes/origin/HEAD</span></span>
<span class="line"><span>.git/refs/remotes/origin/main</span></span>
<span class="line"><span>.git/refs/stash</span></span></code></pre></div><p>人們在本帖回覆中提到的其他一些參考資料：</p>`,30)),n("ul",null,[n("li",null,[s[1]||(s[1]=n("code",null,"refs/notes/*",-1)),s[2]||(s[2]=a("，來自 ",-1)),i(e,{href:"https://tylercipriani.com/blog/2022/11/19/git-notes-gits-coolest-most-unloved-feature/"},{default:t(()=>[...s[0]||(s[0]=[n("code",null,"git notes",-1)])]),_:1})]),s[3]||(s[3]=n("li",null,[n("code",null,"refs/pull/123/head"),a(" 和 "),n("code",null,"refs/pull/123/head`` 用於 GitHub 拉取請求（可通過 "),a("git fetch origin refs/pull/123/merge` 獲取）")],-1)),s[4]||(s[4]=n("li",null,[n("code",null,"refs/bisect/*"),a("，來自 "),n("code",null,"git bisect")],-1))]),s[21]||(s[21]=p(`<h3 id="合併提交不是空的" tabindex="-1">合併提交不是空的 <a class="header-anchor" href="#合併提交不是空的" aria-label="Permalink to “合併提交不是空的”">​</a></h3><p>這是一個示例 Git 倉庫，其中我創建了兩個分支 <code>x</code> 和 <code>y</code>，每個分支都有一個文件（<code>x.txt</code> 和 <code>y.txt</code>），然後將它們合併。讓我們看看合併提交。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline</span></span>
<span class="line"><span>96a8afb (HEAD -&gt; y) Merge branch &#39;x&#39; into y</span></span>
<span class="line"><span>0931e45 y</span></span>
<span class="line"><span>1d8bd2d (x) x</span></span></code></pre></div><p>如果我運行 <code>git show 96a8afb</code>，合併提交看起來是“空的”：沒有差異！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git show 96a8afb</span></span>
<span class="line"><span>commit 96a8afbf776c2cebccf8ec0dba7c6c765ea5d987 (HEAD -&gt; y)</span></span>
<span class="line"><span>Merge: 0931e45 1d8bd2d</span></span>
<span class="line"><span>Author: Julia Evans &lt;julia@jvns.ca&gt;</span></span>
<span class="line"><span>Date:   Fri Oct 20 14:07:00 2023 -0400</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Merge branch &#39;x&#39; into y</span></span></code></pre></div><p>但是，如果我單獨比較合併提交與其兩個父提交之間的差異，你會發現當然<strong>有</strong>差異：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git diff 0931e45 96a8afb   --stat</span></span>
<span class="line"><span>    x.txt | 1 +</span></span>
<span class="line"><span>    1 file changed, 1 insertion(+)</span></span>
<span class="line"><span>$ git diff 1d8bd2d 96a8afb   --stat</span></span>
<span class="line"><span>    y.txt | 1 +</span></span>
<span class="line"><span>    1 file changed, 1 insertion(+)</span></span></code></pre></div><p>現在回想起來，合併提交併不是實際上“空的”（它們是倉庫當前狀態的快照，就像任何其他提交一樣），這一點似乎很明顯，只是我以前從未思考為什麼它們看起來為空。</p><p>顯然，這些合併差異為空的原因是合併差異只顯示<strong>衝突</strong> —— 如果我創建一個帶有合併衝突的倉庫（一個分支在同一文件中添加了 <code>x</code>，而另一個分支添加了 <code>y</code>），然後查看我解決衝突的合併提交，它看起來會像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git show HEAD</span></span>
<span class="line"><span>commit 3bfe8311afa4da867426c0bf6343420217486594</span></span>
<span class="line"><span>Merge: 782b3d5 ac7046d</span></span>
<span class="line"><span>Author: Julia Evans &lt;julia@jvns.ca&gt;</span></span>
<span class="line"><span>Date:   Fri Oct 20 15:29:06 2023 -0400</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Merge branch &#39;x&#39; into y</span></span>
<span class="line"><span></span></span>
<span class="line"><span>diff --cc file.txt</span></span>
<span class="line"><span>index 975fbec,587be6b..b680253</span></span>
<span class="line"><span>--- a/file.txt</span></span>
<span class="line"><span>+++ b/file.txt</span></span>
<span class="line"><span>@@@ -1,1 -1,1 +1,1 @@@</span></span>
<span class="line"><span>- y</span></span>
<span class="line"><span>    -x</span></span>
<span class="line"><span>++z</span></span></code></pre></div><p>這似乎是在告訴我，一個分支添加了 <code>x</code>，另一個分支添加了 <code>y</code>，合併提交通過將 <code>z</code> 替代衝突解決了它。但在前面的示例中，沒有衝突，所以 Git 並未顯示任何差異。</p><p>（感謝 Jordi 告訴我合併差異的工作原理）</p><h3 id="先這樣吧" tabindex="-1">先這樣吧 <a class="header-anchor" href="#先這樣吧" aria-label="Permalink to “先這樣吧”">​</a></h3><p>些寫到這裏吧，也許我將在學到更多 Git 知識時撰寫另一篇關於 Git 的知識的Blog文章。</p><p><em>（題圖：MJ/03bfecc3-944e-47a0-a4fd-575293d2ba92）</em></p><hr>`,16)),n("p",null,[s[6]||(s[6]=a("via: ",-1)),i(e,{href:"https://jvns.ca/blog/2023/10/20/some-miscellaneous-git-facts/"},{default:t(()=>[...s[5]||(s[5]=[a("https://jvns.ca/blog/2023/10/20/some-miscellaneous-git-facts/",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=a("作者：",-1)),i(e,{href:"https://jvns.ca/"},{default:t(()=>[...s[7]||(s[7]=[a("Julia Evans",-1)])]),_:1}),s[12]||(s[12]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 譯者：",-1)),i(e,{href:"https://github.com/KaguyaQiang"},{default:t(()=>[...s[9]||(s[9]=[a("KaguyaQiang",-1)])]),_:1}),s[14]||(s[14]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const C=l(g,[["render",r]]);export{y as __pageData,C as default};
